/* Game-owned simulation time and callback ownership. Engine clocks still animate UI/audio. */
(() => {
  "use strict";
  class Lifecycle {
    constructor() {
      this.epoch = 0;
      this.time = 0;
      this.tasks = new Set();
      this.cleanups = new Set();
    }
    guard(fn) {
      if (typeof fn !== "function") return fn;
      const epoch = this.epoch;
      return (...args) => (epoch === this.epoch ? fn(...args) : undefined);
    }
    own(dispose) {
      this.cleanups.add(dispose);
      return () => this.cleanups.delete(dispose);
    }
    after(seconds, fn) {
      if (!Number.isFinite(seconds) || seconds < 0)
        throw new Error("Invalid simulation delay");
      const task = { remaining: seconds, fn: this.guard(fn) };
      this.tasks.add(task);
      return { cancel: () => this.tasks.delete(task) };
    }
    update(dt) {
      this.time += dt;
      for (const task of [...this.tasks]) {
        if (!this.tasks.has(task)) continue;
        task.remaining -= dt;
        if (task.remaining <= 0) {
          this.tasks.delete(task);
          task.fn();
        }
      }
    }
    exit() {
      this.epoch++;
      this.tasks.clear();
      for (const dispose of this.cleanups) dispose();
      this.cleanups.clear();
    }
    reset(time = 0) {
      this.exit();
      this.time = time;
    }
    dispose() {
      this.exit();
    }
  }
  globalThis.DustRuntime = { ...globalThis.DustRuntime, Lifecycle };
})();

